import { graphql } from "@/gql";

/**
 * Every GraphQL operation the storefront sends, in one place. `graphql()` is
 * generated by `npm run codegen`, so each document is fully typed: a field
 * that does not exist in the schema is a compile error, not a runtime one.
 */

export const CartFields = graphql(`
  fragment CartFields on Cart {
    itemCount
    subtotalCents
    discountCents
    discountCode
    freeShippingDiscount
    lines {
      sku
      quantity
      unitPriceCents
      lineTotalCents
      enoughStock
      variant {
        label
        volumeMl
      }
      product {
        slug
        name
      }
    }
  }
`);

export const CartQuery = graphql(`
  query Cart {
    cart {
      ...CartFields
    }
  }
`);

export const CartAdd = graphql(`
  mutation CartAdd($sku: String!, $quantity: Int!) {
    cartAdd(sku: $sku, quantity: $quantity) {
      ...CartFields
    }
  }
`);

export const CartSetQuantity = graphql(`
  mutation CartSetQuantity($sku: String!, $quantity: Int!) {
    cartSetQuantity(sku: $sku, quantity: $quantity) {
      ...CartFields
    }
  }
`);

export const CartRemove = graphql(`
  mutation CartRemove($sku: String!) {
    cartRemove(sku: $sku) {
      ...CartFields
    }
  }
`);

export const CartApplyDiscount = graphql(`
  mutation CartApplyDiscount($code: String!) {
    cartApplyDiscount(code: $code) {
      ...CartFields
    }
  }
`);

export const CartRemoveDiscount = graphql(`
  mutation CartRemoveDiscount {
    cartRemoveDiscount {
      ...CartFields
    }
  }
`);

export const ShippingOptionsQuery = graphql(`
  query ShippingOptions($countryCode: String!) {
    shippingOptions(countryCode: $countryCode) {
      id
      name
      estimate
      priceCents
    }
    paymentAvailable
  }
`);

export const Checkout = graphql(`
  mutation Checkout($input: CheckoutInput!) {
    checkout(input: $input) {
      number
      accessToken
    }
  }
`);

export const StartPayment = graphql(`
  mutation StartPayment($number: String!, $token: String!) {
    startPayment(number: $number, token: $token)
  }
`);

export const OrderFields = graphql(`
  fragment OrderFields on Order {
    number
    status
    paymentStatus
    email
    placedAt
    subtotalCents
    discountCents
    shippingCents
    taxCents
    totalCents
    shippingRateName
    shipName
    shipLines
    shipCountryCode
    canRequestReturn
    items {
      sku
      productName
      variantLabel
      lotNumber
      quantity
      lineTotalCents
    }
    events {
      kind
      message
      at
    }
    shipments {
      carrier
      status
      trackingNumber
      trackingUrl
    }
  }
`);

export const OrderByTokenQuery = graphql(`
  query OrderByToken($number: String!, $token: String!) {
    orderByToken(number: $number, token: $token) {
      ...OrderFields
    }
    paymentAvailable
  }
`);

export const TrackOrderQuery = graphql(`
  query TrackOrder($number: String!, $email: String!) {
    order(number: $number, email: $email) {
      ...OrderFields
    }
  }
`);

export const LotQuery = graphql(`
  query Lot($lotNumber: String!) {
    lot(lotNumber: $lotNumber) {
      productName
      productSlug
      lot {
        lotNumber
        harvestDate
        grove
        mill
        milledAt
        bottledAt
        bestBefore
      }
      documents {
        kind
        title
        url
      }
    }
  }
`);

export const MeQuery = graphql(`
  query Me {
    me {
      id
      email
      firstName
      lastName
      orders {
        ...OrderFields
      }
    }
  }
`);

export const Login = graphql(`
  mutation Login($email: String!, $password: String!) {
    login(email: $email, password: $password) {
      id
    }
  }
`);

export const Register = graphql(`
  mutation Register($input: RegisterInput!) {
    register(input: $input) {
      id
    }
  }
`);

export const Logout = graphql(`
  mutation Logout {
    logout
  }
`);

export const RequestReturn = graphql(`
  mutation RequestReturn($number: String!, $reason: String!) {
    requestReturn(number: $number, reason: $reason)
  }
`);

export const SendContactMessage = graphql(`
  mutation SendContactMessage($name: String!, $email: String!, $reference: String, $message: String!) {
    sendContactMessage(name: $name, email: $email, reference: $reference, message: $message)
  }
`);

export const SubscribeNewsletter = graphql(`
  mutation SubscribeNewsletter($email: String!) {
    subscribeNewsletter(email: $email)
  }
`);

export const SetLanguage = graphql(`
  mutation SetLanguage($locale: String!) {
    setLanguage(locale: $locale)
  }
`);

export const RequestPasswordReset = graphql(`
  mutation RequestPasswordReset($email: String!) {
    requestPasswordReset(email: $email)
  }
`);

export const ResetPassword = graphql(`
  mutation ResetPassword($id: String!, $exp: String!, $sig: String!, $password: String!) {
    resetPassword(id: $id, exp: $exp, sig: $sig, password: $password)
  }
`);

export const MyDataQuery = graphql(`
  query MyData {
    myData
  }
`);

export const DeleteMyAccount = graphql(`
  mutation DeleteMyAccount($password: String!) {
    deleteMyAccount(password: $password)
  }
`);
